mapper.sql:
WHERE a.deleted_yn='N'
  AND (a.application_name LIKE CONCAT('%',#{q},'%') OR a.application_id LIKE CONCAT('%',#{q},'%'))
  AND COALESCE(p.status,'NOT_STARTED') = #{status}

mapper.select:
SELECT application_id AS applicationId,phase,status,progress_percent AS progressPercent,
  owner_name AS ownerName,planned_end_date AS plannedEndDate,notes,updated_by AS updatedBy,updated_at AS updatedAt
  FROM modernization_progress WHERE application_id=#{id}
